select cast(@tu_ngay as smalldatetime) as date_from, cast(@den_ngay as smalldatetime) as date_to
exec rs_DeleteMultipleVouchers @tu_ngay, @den_ngay, @so_ct1, @so_ct2, @ma_ct, @ma_nt, @ma_dvcs, @nguon_dl, @user_id0, @maxLength, @@userID, @@admin, @@language, @@sysDatabaseName, @ma_nk, @u_id0, @u_id2







			&OutlineEntry;
			&JavascriptReportFilter;
			/* <flatten type="Javascript"> */
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'ma_dvcs');
	var o = f.getItem('maxLength');
	o.value = o.maxLength;
	if (!f._listFields) f._listFields = [];
}
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'VoucherCode':
			f._listFields = result[0].Value.split(',');
			f.grid._index$ = -1;
			break;
		case 'Checking':
			var g = f.grid;
			var dFrom = f.getItem('tu_ngay').value, dTo = f.getItem('den_ngay').value, vc = f.getItem('ten_ct%l').value, v = f._language == 'v', id = f.get_id(), h = f.getItem('tu_ngay').field.Label;
			var listFields = ['ma_kh', 'ten_kh', 'ma_ncc', 'ten_ncc', 'ma_tn', 'ten_tn', 'trang_thai', 'dien_giai', 'ma_kho_n', 'ma_kho_x', 'ma_nt', 'ty_gia', 'tien'], hiddenList = ['stt_rec'];

			if (f._limitDays$ != 0) {
				var dateFrom = f.getItemValue('tu_ngay'), dateTo = f.getItemValue('den_ngay');
				var e1 = (v ? 'Trường <span class="Highlight">' + h + '</span> chưa nhập hoặc giá trị nhập không hợp lệ.' : 'Field <span class="Highlight">' + h + '</span> must not be blank or has invalid value.');
				var diffDate = dateDiffInDays(dateFrom, dateTo);
				if (diffDate < 0 || diffDate > f._limitDays$) {
					$func.hideWait(id);
					$message.show(e1, String.format('$find(\'{0}\').getItem(\'tu_ngay\').focus()', id));
					f._checked = false;
					break;
				}
			}

			for (var i = 0; i < listFields.length; i++) {if (f._listFields.indexOf(listFields[i])== -1) hiddenList.push(listFields[i]);}
			if (g._index$ == -1) {
				g._index$ = f._listFields.indexOf('stt_rec');
				f._listFields.splice(g._index$, 1);
			}
			g._alterTitle = [null, [['%d1', dFrom, true], ['%d2', dTo, true], ['%s', vc, true]]];
			g._hiddenFields = [{Fields: hiddenList.join(','), Value: true}, {Fields: f._listFields.join(','), Value: false}];
			g._voucherCode = f.getItemValue('ma_ct');
			g._$k = [];
			break;
		case 'SetUserID':
			f.setItemValue(result[0].Name, result[0].Value);
			break;
		default:
			break;
	}
}
function onChange$Voucher$Code(o) {o.parentForm.request('VoucherCode', 'VoucherCode', ['ma_ct']);}
function dateDiffInDays(d1, d2) {
	var u1 = Date.UTC(d1.getFullYear(), d1.getMonth(), d1.getDate()), u2 = Date.UTC(d2.getFullYear(), d2.getMonth(), d2.getDate());
	return Math.floor((u2 - u1) / 86400000);
}
function onChange$UserID(o) {
	var f = o.parentForm;
	f.request('GetUserID', 'SetUserID', ['u_name0', 'u_name2', ['owner', 'String', o.field.Name]], null);
}
/* </flatten> */







